sp_widget.client_script:
api.controller=function($scope, $window) {

    var c = this;

    c.username = '';
    c.password = '';
    c.loading = false;
    c.error = '';

    c.login = function() {

        c.error = '';

        if (!c.username || !c.password) {

            c.error = 'Please enter username and password.';
            return;
        }

        c.loading = true;

        c.data.action = 'login';
        c.data.username = c.username;
        c.data.password = c.password;

        c.server.update().then(function(response) {

            c.loading = false;

            console.log('FULL RESPONSE:', response);

            if (!response || !response.data) {

                c.error = 'No response received from server.';
                return;
            }

            var data = response.data;

            console.log('LOGIN DATA:', data);
            console.log('SUCCESS:', data.success);
            console.log('ROLE:', data.role);
            console.log('DASHBOARD:', data.dashboard);

            if (data.success && data.dashboard) {

                $window.location.href =
                    $window.location.origin + data.dashboard;

            } else {

                c.error =
                    data.message || 'Login failed.';

            }

        }, function(error) {

            c.loading = false;

            console.log('SERVER ERROR:', error);

            c.error = 'Server error while logging in.';

        });

    };

}

sp_widget.css:
.login-page {
    min-height: 100vh;
    display: flex;
    justify-content: center;
    align-items: center;
    background: #f4f7fb;
    padding: 20px;
}

.login-card {
    width: 100%;
    max-width: 420px;
    background: white;
    padding: 40px;
    border-radius: 18px;
    box-shadow: 0 10px 35px rgba(0, 0, 0, 0.12);
    text-align: center;
}

.logo {
    width: 70px;
    height: 70px;
    margin: 0 auto 15px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #fff3e0;
    border-radius: 50%;
    font-size: 35px;
}

.login-card h1 {
    margin: 0;
    font-size: 28px;
    color: #222;
}

.subtitle {
    margin: 8px 0 30px;
    color: #777;
}

.form-group {
    text-align: left;
    margin-bottom: 20px;
}

.form-group label {
    display: block;
    margin-bottom: 7px;
    font-weight: 600;
    color: #333;
}

.form-group input {
    width: 100%;
    box-sizing: border-box;
    padding: 13px 14px;
    border: 1px solid #d5dbe3;
    border-radius: 8px;
    font-size: 15px;
    outline: none;
}

.form-group input:focus {
    border-color: #ff9800;
}

.login-button {
    width: 100%;
    padding: 14px;
    border: none;
    border-radius: 8px;
    background: #ff9800;
    color: white;
    font-size: 16px;
    font-weight: 600;
    cursor: pointer;
}

.login-button:hover {
    background: #f57c00;
}

.login-button:disabled {
    opacity: 0.7;
}

.error-message {
    margin-bottom: 15px;
    padding: 10px;
    border-radius: 6px;
    background: #ffebee;
    color: #c62828;
    text-align: left;
}

sp_widget.script:
(function() {

    data.success = false;
    data.message = '';
    data.dashboard = '';

    if (input && input.action == 'login') {

        var login = new CampusFoodLogin();

        var result = login.validateLogin(
            input.username,
            input.password
        );

        data.success = result.success;
        data.message = result.message;
        data.userId = result.userId;
        data.userName = result.userName;
        data.role = result.role;
        data.dashboard = result.dashboard;
    }

})();
